// Private file storage. Local-disk driver: files live under STORAGE_DIR,
// which is never served statically — every download goes through an
// authorised route. Swap this module for an S3/R2 driver with the same
// functions when deploying to a host with an ephemeral disk.

import fs from "node:fs";
import fsp from "node:fs/promises";
import path from "node:path";
import crypto from "node:crypto";
import { env } from "../config/env.js";

const root = env.storageDir;

// Keys are generated by us, but resolve defensively anyway.
function resolveKey(key) {
  const full = path.resolve(root, key);
  if (!full.startsWith(root + path.sep)) throw new Error("Invalid storage key");
  return full;
}

export async function put(key, buffer) {
  const full = resolveKey(key);
  await fsp.mkdir(path.dirname(full), { recursive: true });
  await fsp.writeFile(full, buffer, { flag: "wx" });
  return key;
}

export async function move(fromKey, toKey) {
  const to = resolveKey(toKey);
  await fsp.mkdir(path.dirname(to), { recursive: true });
  await fsp.rename(resolveKey(fromKey), to);
  if (isPendingKey(fromKey)) await fsp.rm(resolveKey(metaKey(fromKey)), { force: true });
  return toKey;
}

// Pending uploads keep their original name/size/pages in a sidecar file.
const metaKey = (pendingKey) => pendingKey.replace(/\.pdf$/, ".json");
export const writePendingMeta = (key, meta) => fsp.writeFile(resolveKey(metaKey(key)), JSON.stringify(meta));
export async function readPendingMeta(key) {
  try {
    return JSON.parse(await fsp.readFile(resolveKey(metaKey(key)), "utf8"));
  } catch {
    return { fileName: "document.pdf", sizeBytes: null, pages: null };
  }
}

export async function exists(key) {
  try {
    await fsp.access(resolveKey(key));
    return true;
  } catch {
    return false;
  }
}

export const readStream = (key) => fs.createReadStream(resolveKey(key));

export async function remove(key) {
  if (!key) return;
  await fsp.rm(resolveKey(key), { force: true });
}

export const newPendingKey = () => `pending/${crypto.randomBytes(16).toString("hex")}.pdf`;

export const isPendingKey = (key) => /^pending\/[a-f0-9]{32}\.pdf$/.test(key);

// Delete abandoned uploads (uploaded but never attached to a material).
export async function sweepPending(maxAgeMs = 24 * 3600 * 1000) {
  const dir = path.join(root, "pending");
  let names = [];
  try {
    names = await fsp.readdir(dir);
  } catch {
    return 0;
  }
  let removed = 0;
  for (const n of names) {
    const full = path.join(dir, n);
    const st = await fsp.stat(full).catch(() => null);
    if (st && Date.now() - st.mtimeMs > maxAgeMs) {
      await fsp.rm(full, { force: true });
      removed++;
    }
  }
  return removed;
}
